"""Build the 0.8 codex, visual report and full architectural audit from actual data.
Run browser suites first. All embedded images are captures, not concept art.
"""
from pathlib import Path
import json,base64,html,re,subprocess,hashlib,collections
R=Path(__file__).resolve().parents[1];D=R/'docs';D.mkdir(exist_ok=True)
def load(p):return json.loads((R/p).read_text())
C=load('src/content.json');rooms={r['id']:r for r in C['rooms']};audit=load('qa/spatial-audit.json')
subprocess.run(['node','--input-type=module','-e',"import fs from 'node:fs';import {CONTENT} from './src/content.js';import {spatialPlanSVG} from './src/spatial.js';fs.writeFileSync('qa/spatial-plans.json',JSON.stringify(Object.fromEntries(CONTENT.rooms.map(r=>[r.id,spatialPlanSVG(r.id)]))));"],cwd=R,check=True)
plans=load('qa/spatial-plans.json');main=load('qa/sweep.json');explore=load('qa/spatial-sweep.json');signals=load('qa/signals-sweep.json')['runs']
bfiles=['browser-results.json','browser-v04-results.json','browser-v05-results.json','browser-v06-results.json','browser-v07-results.json','browser-v08-results.json']
browsers=[load('qa/'+f) for f in bfiles];checks=[x for o in browsers for x in o['checks']];captures={s['file']:s for o in browsers for s in o.get('captures',[])}
combined={'version':'0.8.0','pass':sum(bool(x['ok']) for x in checks),'fail':sum(not x['ok'] for x in checks),'sources':bfiles,'errors':[e for o in browsers for e in o.get('errors',[])], 'htmlSha256':hashlib.sha256((R/'JOUER_ISOLATION.html').read_bytes()).hexdigest(),'captureCount':len(captures),'architecturalFrames':len(browsers[-1]['roomCaptures'])}
(R/'qa/browser-combined-results.json').write_text(json.dumps(combined,ensure_ascii=False,indent=2)+'\n')
node_text=(R/'qa/node-tests-v08.txt').read_text();nodepass=int(re.search(r'^# pass (\d+)',node_text,re.M)[1]);nodefail=int(re.search(r'^# fail (\d+)',node_text,re.M)[1])
M=dict(version='0.8.0',rooms=len(rooms),links=len(C['links']),portalFaces=2*len(C['links']),props=sum(len(r['props']) for r in C['rooms']),rules=len(C['rules']),logs=len(C['logs']),optional=len(C['optional']),chapters=len(C['chapters']),goals=len(C['goals']),assets=len(list((R/'assets').rglob('*.svg'))),nodePass=nodepass,nodeFail=nodefail,browserPass=combined['pass'],browserFail=combined['fail'],captureCount=len(captures),architectureFrames=len(browsers[-1]['roomCaptures']),localPaths=audit['localPaths'],samples=audit['samples'],nativeIntegration=False,nativePersistenceVerified=False,pushed=False,deployed=False)
esc=lambda s:html.escape(str(s),quote=True)
def table(head,rows,cls=''):
 return '<div class="scroll"><table class="'+cls+'"><thead><tr>'+''.join('<th>'+esc(h)+'</th>' for h in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def v(o):return esc(json.dumps(o,ensure_ascii=False))
def chip(k,label):return f'<div class="metric"><strong>{M[k]}</strong><span>{label}</span></div>'
CSS='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#071512;color:#d5ddca;font:16px/1.65 system-ui,Segoe UI,sans-serif}header{padding:64px max(4vw,22px) 36px;background:linear-gradient(120deg,#294032,#081913);border-bottom:1px solid #6c7f59}header>div,main{max-width:1240px;margin:auto}main{padding:24px 25px 80px}h1{font-size:clamp(32px,4.6vw,61px);font-weight:450;line-height:1.12;letter-spacing:-.015em;max-width:970px}h2{font-size:29px;line-height:1.2;font-weight:500;margin:50px 0 20px}h3{font-size:21px;font-weight:500;margin-top:26px}.eyebrow{font:11px/1.6 monospace;letter-spacing:.13em;color:#b9cbb0}.lead{font-size:20px;max-width:960px;color:#b8c9ae}nav{display:flex;gap:10px;flex-wrap:wrap;margin-top:25px}a{color:#d0ddb4}nav a,.button,button{border:1px solid #667f58;background:#223b29;padding:9px 14px;text-decoration:none;color:#d8e0c3}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:14px;margin:25px 0}.metric{padding:19px;border:1px solid #48634e;background:#10271c}.metric strong{display:block;font-size:34px;line-height:1.3;font-weight:500}.metric span{font-size:12px;color:#b6c7a9}.good,.warn{padding:21px 25px;border-left:4px solid #91b773;background:#1b3523;margin:24px 0}.warn{background:#302d1c;border-color:#c6a467;color:#e4d7b8}.fine{font-size:12px;color:#a3b998}.scroll{overflow-x:auto;max-width:100%;margin:20px 0}table{width:100%;border-collapse:collapse;font-size:13px;line-height:1.5}th,td{vertical-align:top;padding:11px 13px;border-bottom:1px solid #40593e;overflow-wrap:anywhere}th{background:#233d28;color:#d8d9b5;text-align:left}code,pre{font:12px/1.6 monospace;color:#b9cba7;overflow-wrap:anywhere}pre{padding:17px;background:#07110c;white-space:pre-wrap}.room,.card{padding:24px;margin:20px 0;border:1px solid #4b654a;background:#11261a}.room[hidden]{display:none}.spatial-plan{display:block;width:100%;height:auto;margin:18px 0;border:1px solid #627e58}details{border:1px solid #3e5a40;padding:14px;margin:16px 0}summary{cursor:pointer;color:#d3debf}figure{margin:30px 0;background:#102219;border:1px solid #506b4c}figure img{display:block;width:100%;height:auto}figcaption{padding:19px 23px;font-size:14px;color:#b6c8ab}figcaption strong{font-size:19px;display:block;color:#d6ddc4;margin-bottom:8px}.searchbar{display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:15px;background:#172f20f5;position:sticky;top:0;z-index:10;border:1px solid #667b54}input{min-width:160px;flex:1;background:#071b11;color:#e1e4c9;border:1px solid #7f9668;font-size:15px;padding:12px}footer{margin-top:50px;border-top:1px solid #506a43;padding:25px 0;font-size:12px;color:#a1b291}.ok{color:#bdd7a2}.bad{color:#e0ac81}.tag{font:11px monospace;padding:5px 8px;background:#365236}.legend{font:12px/1.6 monospace;color:#b1c4a5}@media(max-width:650px){header{padding:35px 20px}main{padding:20px 14px 65px}.room,.card{padding:14px}h2{font-size:25px}.lead{font-size:17px}td,th{padding:8px;font-size:11px}.grid{grid-template-columns:repeat(2,1fr)}nav a{font-size:12px}.searchbar{position:relative}}@media print{body{background:white;color:black}header,.card,.room{background:white;color:black}.searchbar,nav{display:none}details{break-inside:avoid}.room{break-before:page}}'''
def page(title,lead,body):
 return '<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title)+' · Isolation 0.8</title><style>'+CSS+'</style></head><body><header><div><div class="eyebrow">ALIENS: TANTALUS FRONTIER / ALIEN: ISOLATION / 0.8.0</div><h1>'+title+'</h1><p class="lead">'+lead+'</p><div class="eyebrow">UNE STATION, DES CHEMINS · LIVRAISON LOCALE · 29 SEPTEMBRE 2026</div></div></header><main>'+body+'<footer>Prototype autonome non officiel. Plans, textes et graphismes originaux stylisés. Aucune fusion native Tantalus, aucun push GitHub et aucun déploiement Vercel. Les géométries sont condensées et ne reproduisent pas chaque pièce du jeu commercial.</footer></main></body></html>'
def figure(file,title,provenance):
 p=R/'qa'/file;mime='image/jpeg' if p.suffix=='.jpg' else 'image/png';b64=base64.b64encode(p.read_bytes()).decode()
 return '<figure><img loading="lazy" alt="'+esc(title)+'" src="data:'+mime+';base64,'+b64+'"><figcaption><strong>'+esc(title)+'</strong>'+esc(provenance)+'</figcaption></figure>'
linksByRoom={r:[e for e in C['links'] if r in (e['a'],e['b'])] for r in rooms}
types={'door':'Porte','stairs':'Escalier','lift':'Ascenseur','tram':'Tram','shuttle':'Navette','transfer':'Transfert EVA','vent':'Conduit','memory':'Récit','walkway':'Passerelle ouverte','passage':'Arche'}
wallNames={'L':'Paroi gauche','R':'Paroi droite','N':'Paroi de fond'}
def lock(e):
 s=['chapitre '+str(e['min']+1)] if e['min'] else []
 if e.get('flag'):s.append('condition '+e['flag'])
 if e.get('deny'):s.append('fermé après '+e['deny'])
 if e.get('blockedTo'):s.append('sens bloqué vers '+e['blockedTo']+' après '+str(e.get('blockFlag')))
 if e['kind']=='vent':s.append('accroupissement')
 return '; '.join(s) or 'pas de verrou de progression'
limits='''<h2 id="limites">Périmètre et limites</h2><p><strong>76 lieux du module sont présents et reliés structurellement ; ce n’est pas chaque pièce du jeu commercial.</strong> La matrice couvre les principales familles de lieux sous une forme condensée. Les agencements et raccords sont originaux, pas des plans officiels ni une reconstitution métrique de Sevastopol.</p><p>Le plan local utilise les mêmes ouvertures, approches, arrivées et obstacles que le jeu. La grande carte est un réseau schématique : une orientation à l’écran n’impose pas une orientation géographique globale. Les couloirs de liaison, trajets de tram et changements d’étage restent des transitions condensées, pas un volume 3D continu. Le souvenir de Marlow est un changement narratif, pas une porte entre une planète et la station.</p><p>La campagne garde ses verrous, ruptures et risques. Un graphe structurel connecté ne signifie pas que toutes les pièces sont ouvertes dès le départ ou que tous les retours sont possibles après le détachement de KG-348. Les campagnes automatiques lisent l’état interne pour planifier : ce ne sont pas des essais humains. Les parcours géométriques désactivent les dégâts et les ennemis ordinaires ; ils conservent le chasseur nécessaire à Gemini.</p><p>Le rendu reste vectoriel stylisé. Les 155 SVG sont conservés, les cadres et sols supplémentaires étant tracés par le moteur. Les deux escortes et refuges restent locaux, pas une évacuation de Sevastopol. Le graphe de gaine temporisé, la patrouille contrôlée en confinement et les séquences finales condensées sont inchangés dans leur principe.</p><p><strong>Le lancement natif et le stockage après fermeture restent non certifiés.</strong> Les navigations file:// et HTTP local ont effectivement été refusées par la politique du navigateur. Les contrôles exécutent le HTML exact via Page.set_content, sans modifier cette politique ; certains essais de stockage utilisent un double en mémoire indiqué dans leur provenance. Aucun test de production, fusion GameEngine/SaveSystem, push ou déploiement n’a été effectué.</p>'''
proof='<h2 id="preuves">Résultats enregistrés</h2><div class="grid">'+''.join(chip(k,l)for k,l in [('nodePass','tests Node réussis'),('browserPass','contrôles Chromium réussis'),('localPaths','trajets locaux contrôlés'),('portalFaces','faces de passage')])+'</div>'
proof+='<p>Le contrôle indépendant échantillonne <strong>'+str(audit['samples'])+'</strong> points sur '+str(audit['localPaths'])+' trajets produits par le pathfinding du jeu. Chaque pièce est parcourue de ses points d’arrivée vers ses autres accès, objectifs, tâches, archives et postes utilisables. Les collisions sont réellement interrogées. Ce contrôle préparé ne prouve ni tous les points continus possibles, ni la survie.</p>'
proof+=table(['Série','Configuration','Résultat','Portée'],[
 ['Campagne principale','3 graines × 3 difficultés',str(sum(r['ok'] for r in main))+'/9 terminées','IA, dégâts et ressources finis ; 52 objectifs'],
 ['Campagnes détecteur','3 graines × haut-parleur actif/coupé',str(sum(r['ok'] for r in signals))+'/6 terminées','Récit ; essais distincts des nouvelles annexes'],
 ['Exploration active complète','Récit, 3 graines',str(sum(r['ok'] for r in explore if r['active']))+'/3 terminées','76 lieux, 32 tâches, deux escortes et deux projets dans les deux succès'],
 ['Exploration géométrique','Normale et CLASSIC',str(sum(r['ok'] for r in explore if not r['active']))+'/2 terminées','52 objectifs, 32 tâches, 76 lieux, 158 transitions ; menace neutralisée comme décrit'],
 ['Architecture au navigateur','76 lieux × 3 cadrages',str(M['architectureFrames'])+' images','Deux extrémités en vue normale et un centre CLASSIC, états préparés'],
 ['Node / Chromium',str(nodepass)+' / '+str(combined['pass'])+' assertions','0 échec final','Fixtures et commandes clavier/souris ; journaux complets fournis']])
proof+='<div class="warn"><strong>Un décès sur les trois essais d’exploration.</strong> La graine 20141007 meurt dans la salle de garde <code>m_staff</code>, après 13 objectifs, 5 tâches et 22 lieux visités, avant le premier recrutement. Les graines 42 et 29102026 terminent avec 52 objectifs, 32 tâches, 76 lieux et 158 transitions chacune. Le journal d’échec est conservé ; il n’est pas transformé en succès par une invulnérabilité.</div>'
proof+=table(['Difficulté','Graine','Résultat','Objectifs','Dégâts cumulés'],[[esc(r['difficulty']),r['seed'],'TERMINÉ' if r['ok'] else 'MORT',str(r['goals'])+'/52',r['damage']] for r in main])
proof+='<p class="fine">Sources de preuve : qa/spatial-audit.json, qa/spatial-sweep.json, qa/sweep.json, qa/signals-sweep.json, qa/node-tests-v08.txt et les six fichiers browser-…-results.json. Les 536 assertions comprennent les tests historiques réexécutés et les nouvelles assertions spatiales, pas seulement des tests ajoutés.</p>'
# Visual report: 14 current spatial shots + 4 retained-system shots + two fixed architecture inspections.
selected=['captures/83_menu_spatial.png','captures/84_plan_morgue.png']+[f'captures/{85+i}_O{21+i}_local.png'for i in range(12)]+['captures/60_projet_medical.png','captures/63_journal_technical.png','captures/74_roue.png','captures/76_detecteur.png']
frames=browsers[-1]['roomCaptures'];extra=[next(s for s in frames if s['room']==id and s['side']=='L' and not s['classic']) for id in ['f_surface','e_antenna']]
M['reportScreenshots']=len(selected)+len(extra)
body='<div class="good"><strong>Une architecture locale commune au jeu, à la carte et au codex.</strong> Les portes sont ancrées à une paroi ou une enveloppe, les escaliers signalent un changement de pont et les approches sont distinctes des arrivées. Aucun déplacement ne peut être déclenché depuis la carte.</div><div class="grid">'+''.join(chip(k,l)for k,l in [('rooms','lieux'),('links','liaisons réciproques'),('props','placements'),('optional','tâches facultatives'),('assets','SVG conservés')])+'</div><nav><a href="#delta">CHANGEMENTS</a><a href="#preuves">TESTS</a><a href="#captures">CAPTURES</a><a href="#limites">LIMITES</a></nav><h2 id="delta">De la 0.7 à la 0.8</h2>'
body+=table(['Domaine','Travail livré'],[
 ['Portes et murs','224 faces de passage avec support architectural, code P001 à P112, point d’approche et point d’arrivée. Les accès de fond ne sont plus dessinés au milieu du plan de marche.'],
 ['Verticalité','9 anciennes portes entre des ponts différents deviennent des escaliers visibles. Un ancien escalier au même niveau devient un passage de plain-pied. Ces raccords restent des transitions condensées.'],
 ['Circulation','Espacement minimal de 205 unités entre façades de fond, corrections de 12 postes interactifs et de 6 corridors d’arrivée. Les enregistrements incluent aussi des arrondis de coordonnées : 82 lignes de changements, pas 82 bugs distincts.'],
 ['Niveaux','12 nouveaux lieux, 24 nouvelles liaisons, 132 nouveaux placements. Les 64 anciens lieux, 88 anciennes liaisons, 708 identifiants de props, 19 chapitres et 52 objectifs sont conservés.'],
 ['Progression','La carte de Morley est exigée sur tous les accès de la pharmacie. Les nouvelles issues de KG-348 se ferment avec le module. Les annexes exposées sont raccordées au réseau du chasseur.'],
 ['Carte','Inspection des 76 plans locaux, portes voisines consultables, conditions d’ouverture, repère manuel enregistré et trajet vers le prochain code de seuil. Carte globale explicitement schématique.'],
 ['Rendu','Sols extérieurs ramenés sous le plan de marche, passages rocheux et organiques sans cadres de sas Seegson dans le souvenir, pas de grille de plafond flottante dans le vide, signalétique adaptée au secteur ; 23 affiches ou luminaires déplacés hors des ouvertures.'],
 ['Compatibilité','Import d’une sauvegarde réelle du format 0.7, maintien des fixtures 0.1–0.6. Migration des repères invalide les identifiants absents, sans accorder de nouveaux objectifs. Mise à jour du véritable lanceur 0.7, retour arrière exact sur hôte temporaire.']])
body+='<h2>Douze espaces supplémentaires</h2>'+table(['Lieu','Pont / vue','Fonction architecturale'],[[esc(rooms[id]['name']),str(rooms[id]['deck'])+' / '+rooms[id]['view'],esc(rooms[id]['architecture'])] for id in C['spatialRevision']['newRooms']])
body+=proof+limits+'<h2 id="captures">'+str(M['reportScreenshots'])+' captures sélectionnées</h2><p>Les '+str(M['captureCount'])+' captures PNG des mécaniques et de la progression sont incluses dans qa/captures. Les '+str(M['architectureFrames'])+' images JPEG préparées pour l’inspection sont dans qa/architecture. Dix planches-contact donnent les deux extrémités de chaque lieu. Aucune image conceptuelle n’est présentée comme du gameplay.</p>'
for file in selected:
 s=captures[file];body+=figure(file,s['title'],s['provenance'])
for s in extra:body+=figure(s['file'],rooms[s['room']]['name']+' · architecture corrigée',s['provenance'])
body+='<h2>Reproduire</h2><pre>npm test\nnpm run test:spatial\nnpm run test:campaign\nnpm run test:signals\nnpm run test:browser\nnpm run docs:build\nnpm run test:documents\npython3 tools/verify_delivery.py</pre><p>Node 20 ou supérieur pour le moteur et le lanceur ; Python et Playwright avec Chromium pour les contrôles de navigateur. Les tests réécrivent leurs journaux : conserver une copie extraite intacte avant de les relancer.</p>'
(D/'RAPPORT_VISUEL_ISOLATION.html').write_text(page('Rapport visuel<br>Une station, des chemins','Version 0.8.0 · Changements jouables, cohérence locale et limites de la validation.',body))
# Room-by-room codex, generated from runtime data rather than manually repeated counts.
body='<div class="warn"><strong>Plan technique local, pas plan officiel.</strong> Les noms de grandes familles servent au contrôle de couverture ; chaque pièce et chaque raccord sont une adaptation condensée. La circulation de profil aplatit la profondeur mais conserve les données de collision.</div><div class="grid">'+''.join(chip(k,l)for k,l in [('rooms','plans locaux'),('props','placements inventoriés'),('portalFaces','faces de passage'),('rules','règles de conception')])+'</div><nav><a href="#lieux">LIEUX</a><a href="#taches">TÂCHES</a><a href="#archives">ARCHIVES</a><a href="#regles">RÈGLES</a><a href="#systemes">SYSTÈMES</a></nav><h2 id="lieux">Les 76 lieux</h2><div class="searchbar"><label for="roomSearch">Rechercher un lieu, prop ou accès</label><input id="roomSearch" type="search" placeholder="Morgue, relais, P017, supply.eva_filter…"><button id="resetSearch">Tout afficher</button><span id="searchCount">76 / 76</span></div>'
for r in C['rooms']:
 body+='<article class="room" id="room-'+r['id']+'"><span class="tag">'+esc(r['sector'])+' · PONT '+str(r['deck'])+' · '+r['view']+'</span><h2>'+esc(r['name'])+'</h2><code>'+r['id']+'</code><p>'+esc(r['architecture'])+'</p>'+plans[r['id']]
 pr=[]
 for e in linksByRoom[r['id']]:
  side='a'if e['a']==r['id']else'b';other=e['b']if side=='a'else e['a'];p=e[side+'Portal']
  pr.append([e['spatial']['labelId'],'<a href="#room-'+other+'">'+esc(rooms[other]['name'])+'</a>',types[e['kind']]+' · '+str(r['deck'])+' → '+str(rooms[other]['deck']),wallNames[p['wall']]+' / '+p['mount'],f"({p['x']}, {p['y']})",v(p['approach']),v(p['arrival']),esc(lock(e))])
 body+=table(['Code','Voisin','Nature / ponts','Support','Ouverture','Approche','Arrivée locale','Conditions'],pr,'portal-table')
 body+='<details open><summary>'+str(len(r['props']))+' placements et fonctions</summary>'+table(['Identifiant','Type','Position','Empreinte','Collision / couverture','Interaction','Fonction'],[['<code>'+esc(p['id'])+'</code>',esc(p['kind']),f"{p['x']}, {p['y']}",f"{p['w']} × {p['d']}",('solide'if p['solid'] else 'non solide')+(' / couverture' if p.get('cover') else ' / sans couverture'),esc(p.get('interactive','—')),esc(p['purpose'])] for p in r['props']],'prop-table')+'</details>'
 body+='<p class="fine">Objectifs principaux : '+esc(', '.join(g['id']+' '+g['label']for g in C['goals']if g['room']==r['id'])or'aucun')+'<br>Tâches : '+esc(', '.join(g['id']+' '+g['label']for g in C['optional']if g['room']==r['id'])or'aucune')+'<br>Archives : '+esc(', '.join(g['id']+' '+g['title']for g in C['logs']if g['room']==r['id'])or'aucune')+'</p></article>'
