body+='<h2 id="archives">57 archives originales</h2>'+''.join('<article class="card archive"><code>'+l['id']+' / '+l['room']+'</code><h3>'+esc(l['title'])+'</h3><p>'+esc(l['text'])+'</p></article>'for l in C['logs'])
